import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] sorted = new int[n];
        for (int i = 0; i < n; i++) sorted[i] = sc.nextInt();
        int target = sc.nextInt();
        System.out.println(pairSumExists(sorted, target));
    }

    static int pairSumExists(int[] sorted, int target) {
        int lo = 0, hi = sorted.length - 1;
        while (lo < hi) {
            int sum = sorted[lo] + sorted[hi];
            if (sum == target) return 1;
            if (sum < target) lo++;
            else hi--;
        }
        return 0;
    }
}

