public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] ids = new int[n];
        for (int i = 0; i < n; i++) ids[i] = sc.nextInt();
        System.out.println(countEvenParity(ids));
    }

    static int countEvenParity(int[] ids) {
        int count = 0;
        for (int v : ids) {
            int bits = 0;
            int x = v;
            while (x != 0) {
                x &= x - 1;
                bits++;
            }
            if (bits % 2 == 0) count++;
        }
        return count;
    }
}

