        so.println(maxSubarraySum(values));
    }

    static long maxSubarraySum(int[] values) {
        long best = values[0];
        long cur = values[0];
        for (int i = 1; i < values.length; i++) {
            cur = Math.max(values[i], cur + values[i]);
            if (cur > best) best = cur;
        }
        return best;
    }
}

