        so.println(missingNumber(values));
    }

    static long missingNumber(int[] values) {
        int n = values.length;
        long expected = (long) n * (n + 1) / 2;
        long actual = 0;
        for (int v : values) {
            actual += v;
        }
        return expected - actual;
    }
}

