public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] sizes = new int[n];
        for (int i = 0; i < n; i++) sizes[i] = sc.nextInt();
        int budget = sc.nextInt();
        so.println(longestBudgetWindow(sizes, budget));
    }

    static int longestBudgetWindow(int[] sizes, int budget) {
        int best = 0, sum = 0, start = 0;
        for (int end = 0; end < sizes.length; end++) {
            sum += sizes[end];
            while (sum > budget) {
                sum -= sizes[start];
                start++;
            }
            int len = end - start + 1;
            if (len > best) best = len;
        }
        return best;
    }
}

