        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) values[i] = sc.nextInt();
        so.println(equilibriumIndex(values));
    }

    static int equilibriumIndex(int[] values) {
        long total = 0;
        for (int v : values) {
            total += v;
        }
        long leftSum = 0;
        for (int i = 0; i < values.length; i++) {
            long rightSum = total - leftSum - values[i];
            if (leftSum == rightSum) return i;
            leftSum += values[i];
        }
        return -1;
    }
}

