    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] walls = new int[n];
        for (int i = 0; i < n; i++) walls[i] = sc.nextInt();
        so.println(maxWaterArea(walls));
    }

    static int maxWaterArea(int[] walls) {
        int lo = 0, hi = walls.length - 1;
        int best = 0;
        while (lo < hi) {
            int area = Math.min(walls[lo], walls[hi]) * (hi - lo);
            if (area > best) best = area;
            if (walls[lo] < walls[hi]) lo++;
            else hi--;
        }
        return best;
    }
}

