    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] votes = new int[n];
        for (int i = 0; i < n; i++) votes[i] = sc.nextInt();
        so.println(majorityElement(votes));
    }

    static int majorityElement(int[] votes) {
        int candidate = 0, count = 0;
        for (int v : votes) {
            if (count == 0) candidate = v;
            count += (v == candidate) ? 1 : -1;
        }
        count = 0;
        for (int v : votes) {
            if (v == candidate) count++;
        }
        return count > votes.length / 2 ? candidate : -1;
    }
}

