public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] prices = new int[n];
        for (int i = 0; i < n; i++) prices[i] = sc.nextInt();
        so.println(maxPriceJump(prices));
    }

    static long maxPriceJump(int[] prices) {
        long best = -1;
        long minSoFar = prices[0];
        for (int i = 1; i < prices.length; i++) {
            long diff = prices[i] - minSoFar;
            if (diff > 0 && diff > best) best = diff;
            if (prices[i] < minSoFar) minSoFar = prices[i];
        }
        return best;
    }
}
